function validateField(frm, fieldName, errorMessage) {
    if (!frm.doc[fieldName]) {
        frappe.throw(__(errorMessage));
    }
}

function validateChildTable(frm, tableName, requiredFields) {
    let table = frm.doc[tableName];
    if (!table || table.length === 0) {
        frappe.throw(__(`${tableName.replace(/_/g, ' ')} is empty. Please add at least one entry.`));
    }

    for (let row of table) {
        for (let field of requiredFields) {
            if (!row[field.name]) {
                frappe.throw(__(`${field.label} is required in ${tableName.replace(/_/g, ' ')}.`));
            }
        }
    }
}

frappe.ui.form.on('Customer', {
    validate: function(frm) {
        // Validate main fields
        validateField(frm, 'customer_name', 'Customer Name is required');
        validateField(frm, 'custom_mobile_number', 'Customer Mobile Number is required');

        // Validate Vehicle Details And Venue table
        validateChildTable(frm, 'custom_vehicle_information', [
            {name: 'registration_number', label: 'Registration Number'},
            {name: 'brand_and_model', label: 'Brand And Model'},
            {name: 'site_name', label: 'Site Name'},
            {name: 'building_number', label: 'Building Number'},
            {name: 'bay_name', label: 'Bay Name'},
            {name: 'parking_level_number', label: 'Parking Level Number'},
            {name: 'parking_lot_number', label: 'Parking Lot Number'}
        ]);
    }
});

frappe.ui.form.on('Subscription', {
    party: function(frm, cdt, cdn) {
        var customer = frm.doc.party;
        frappe.call({
            method: 'trie_crm.triecrm_functions.custom_vehicle_information',
            args: {
                customer: customer
            },
            callback: function(r) {
                // Clear existing rows in the "Services" child table
                frm.clear_table("custom_vehicle_information");

                if (r.message && r.message.length > 0) {
                    r.message.forEach(vehilce_details => {
                        var child = frm.add_child("custom_vehicle_information");
                        frappe.model.set_value(child.doctype, child.name, "car_type", vehilce_details.car_type);
                        frappe.model.set_value(child.doctype, child.name, "brand_and_model", vehilce_details.brand_and_model);
                        frappe.model.set_value(child.doctype, child.name, "parking_level_number", vehilce_details.parking_level_number);
                        frappe.model.set_value(child.doctype, child.name, "registration_number", vehilce_details.registration_number);
                        frappe.model.set_value(child.doctype, child.name, "car_color", vehilce_details.car_color);
                        frappe.model.set_value(child.doctype, child.name, "parking_lot_number", vehilce_details.parking_lot_number);
                        frappe.model.set_value(child.doctype, child.name, "bay_name", vehilce_details.bay_name);
                        frappe.model.set_value(child.doctype, child.name, "site_name", vehilce_details.site_name);
                        frappe.model.set_value(child.doctype, child.name, "building_number", vehilce_details.building_number);
                        frappe.model.set_value(child.doctype, child.name, "flat_number", vehilce_details.flat_number);
                    });
                }

                // Refresh the form to display the updated child table
                frm.refresh_field("custom_vehicle_information");
            }
        });
    }
});



frappe.ui.form.on('Subscription Plan Detail', {
	plan:function(frm, cdt, cdn) {
		let d=locals[cdt][cdn];
		plan_name=d.plan
		frappe.call({
            method: 'trie_crm.triecrm_functions.update_subscription_service_and_day_table',
            args: {
                plan_name: plan_name,
                registration_number:frm.doc.custom_vehicle_information
            },

		callback: function(r) {
    		if (r.message) {
                // Update plans
                r.message.plans.forEach(plan => {
                    let existingRow = frm.doc.plans.find(p => p.plan === plan.plan);
                    if (existingRow) {
                        frappe.model.set_value(existingRow.doctype, existingRow.name, "custom_package_service_per_week", plan.qty);
                    } else {
                        let newRow = frm.add_child("plans");
                        frappe.model.set_value(newRow.doctype, newRow.name, "plan", plan.plan);
                        frappe.model.set_value(newRow.doctype, newRow.name, "custom_package_service_per_week", plan.qty);
                    }
                });
                frm.refresh_field("plans");

                // Update custom_subscription_day_and_time
                frm.clear_table("custom_subscription_day_and_time");
                r.message.custom_subscription_day_and_time.forEach(item => {
                    let row = frm.add_child("custom_subscription_day_and_time");
                    if (item.vehicle_number) {
                        frappe.model.set_value(row.doctype, row.name, "vehicle_number", item.vehicle_number);
                    }
                    frappe.model.set_value(row.doctype, row.name, "day", item.day);
                });
                frm.refresh_field("custom_subscription_day_and_time");

                // Update custom_vehicle_service
                frm.clear_table("custom_vehicle_service");
                r.message.custom_vehicle_service.forEach(item => {
                    let row = frm.add_child("custom_vehicle_service");
                    frappe.model.set_value(row.doctype, row.name, "vehicle_number", item.vehicle_number);
                    frappe.model.set_value(row.doctype, row.name, "service", item.service);
                    frappe.model.set_value(row.doctype, row.name, "qty", item.qty);
                });
                frm.refresh_field("custom_vehicle_service");
            }
		}
		})

	}
})

frappe.ui.form.on('Subscription Plan', {
    item: function(frm, cdt, cdn) {
        var item_code = frm.doc.item;
        frappe.call({
            method: 'trie_crm.triecrm_functions.get_services_data',
            args: {
                item_code: item_code
            },
            callback: function(r) {
                // Clear existing rows in the "Services" child table
                frm.clear_table("custom_service");

                if (r.message && r.message.length > 0) {
                    r.message.forEach(service => {
                        // console.log(service);
                        var child = frm.add_child("custom_service");
                        frappe.model.set_value(child.doctype, child.name, "services", service.services);
                        frappe.model.set_value(child.doctype, child.name, "qty", service.qty);
                    });
                }

                // Refresh the form to display the updated child table
                frm.refresh_field("Services");
            }
        });
    }
});

frappe.ui.form.on('Subscription', {
    refresh: function(frm) {
        frm.add_custom_button(__('Generate Payment'), () => {
            let d = new frappe.ui.Dialog({
                title: 'Create New Sales Invoice',
                fields: [
                    {
                        label: 'Posting Date',
                        fieldname: 'posting_date',
                        fieldtype: 'Date',
                        default: frappe.datetime.get_today()
                    },
                    {
                        label: 'table',
                        fieldname: 'table',
                        fieldtype: 'HTML',
                        options: `
                        <table class="table">
                        <thead>
                        <tr>
                        <th>Subscription</th>
                        <th>Package</th>
                        <th>Amount</th>
                        <th>Mode Of Payment</th>
                        </tr>
                        </thead>
                        </table>
                        `
                    },
                ],
                primary_action_label: 'Save',
                primary_action(values) {
                    let items = []
                    let all_rows = $(d.$wrapper.find(".table .item-row"));
                    all_rows.each(function(e) {
                        let row = $(this);
                        let item_code = row.find('.item-code').attr("id");
                        let item_name = row.find('.item-name').text();
                        let amount = row.find('.amount').text();
                        let mode_of_payment = row.find('.mode-of-payment').val();
                        items.push({
                            item_code,
                            item_name,
                            amount,
                            mode_of_payment
                        });
                    });
                    frappe.call({
                        method: 'trie_crm.triecrm_functions.create_sales_invoice',
                        args: {
                            subscription: frm.doc.name,
                            customer: frm.doc.party,
                            items: items,
                            posting_date: values.posting_date
                        },
                        callback: function(r) {
                            if (r.message) {

                            }
                            d.hide();
                        }
                    });
                }
            });
            frm.doc.plans.forEach(plan => {
                frappe.db.get_doc('Subscription Plan', plan.plan).then(plan_doc => {
                    d.$wrapper.find(".table").append(`
                        <tr class="item-row">
                            <td>${frm.doc.name}</td>
                            <td class="item-name">${plan_doc.item}</td>
                            <td class="amount">${plan_doc.cost}</td>
                            <td>
                                <select class="mode-of-payment">
                                    <option value="Cash">Cash</option>
                                    <option value="Credit Card">Credit Card</option>
                                </select>
                            </td>
                        </tr>
                    `);
                });
            });
            d.show();
        });
    }
});

frappe.ui.form.on('Subscription', {
    after_save: function(frm) {
        if (frm.doc.custom_subscription_day_and_time.length === 0 && frm.doc.custom_vehicle_service.length === 0) {
            frappe.call({
                method: 'trie_crm.triecrm_functions.update_subscription_plan',
                args: {
                    subscription_name: frm.doc.name
                },
                callback: function(r) {
                    if (r.message) {
                        // updatePlans(frm, r.message.plans);
                        frm.reload_doc();
                    }
                }
            });
        }
    },
    before_save: function(frm) {
        if (frm.is_new()) {
            frm.set_value('status','Unpaid')
            console.log(frm.doc.status)

            frm.refresh_field('status');
            let startDate = frappe.datetime.str_to_obj(frm.doc.start_date);
            let endDate = new Date(startDate.getFullYear() + 5, startDate.getMonth(), startDate.getDate());
            frm.set_value('end_date', frappe.datetime.obj_to_str(endDate));
            frm.set_value('custom_subscription_channel', "Walk-In");
            frm.set_value("custom_remaining_pause_days" ,"60");
        }
    }
});

frappe.ui.form.on('Subscription', {
    before_save: function(frm) {
        if (frm.is_new()) {
            console.log("if")
            frm.doc.status = 'Unpaid';
            frm.refresh_field('status');
            let startDate = frappe.datetime.str_to_obj(frm.doc.start_date);
            let endDate = new Date(startDate.getFullYear() + 5, startDate.getMonth(), startDate.getDate());
            frm.set_value('end_date', frappe.datetime.obj_to_str(endDate));
            frm.set_value('custom_subscription_channel', "Walk-In");
        }
    }
});
